using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using Project_QLThoiTrang.Data;
using Project_QLThoiTrang.Models;
using Project_QLThoiTrang.Services;
using System.Text.Json;
var connection=Environment.GetEnvironmentVariable("QOANH_TEST_CONNECTION")??throw new Exception("Set QOANH_TEST_CONNECTION; deploy delivery/Deploy.sql to a NEW isolated DB first.");
var cs=new SqlConnectionStringBuilder(connection);if(!cs.InitialCatalog.StartsWith("QOANH_Verification_"))throw new Exception("Isolated test database required.");
var factory=new Factory(connection);var store=new StoreService(factory);
if(store.Read(d=>d.ImportedFileHash)!=null)throw new Exception("Use a NEW database deployed with the supplied scripts for each run; no data is deleted/reset by this runner.");
var results=new List<object>();int failed=0;
void Check(string id,string expected,Action action){try{action();results.Add(new{id,expected,status="PASS",error=""});Console.WriteLine("PASS "+id);}catch(Exception e){failed++;results.Add(new{id,expected,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+id+": "+e.Message);}}
void Assert(bool condition,string message="Assertion failed"){if(!condition)throw new Exception(message);}
void Reject(Action action){try{action();}catch(InvalidOperationException){return;}catch(System.ComponentModel.DataAnnotations.ValidationException){return;}throw new Exception("Expected business validation failure");}
int Stock(int id=1)=>store.Read(d=>d.Products.Single(p=>p.Id==id).Stock);
Order Get(string id)=>store.Read(d=>d.Orders.Single(o=>o.Id==id));
CheckoutInput Input(string? code=null)=>new(){Name="Native test",Phone="0901234567",Address="Verification address",CheckoutToken=Guid.NewGuid().ToString("N"),PromotionCode=code};
Variant Variant(int product=1)=>store.Read(d=>d.Variants.First(v=>v.ProductId==product&&v.Active&&v.Stock>0));
List<CartItem> Cart(int quantity=1,int product=1){var v=Variant(product);return new(){new(){ProductId=product,VariantId=v.Id,Size=v.Size,Color=v.Color,Quantity=quantity}};}
Order Place(int quantity=1,int product=1,string? code=null)=>store.PlaceOrder(1,Input(code),Cart(quantity,product));
void Confirm(Order o)=>store.ChangeOrderStatus(o.Id,"Đã xác nhận",-1);
void Paid(Order o)=>store.RecordPayment(o.Id,Get(o.Id).Total,"PAY-"+Guid.NewGuid().ToString("N"),-1);
void Deliver(Order o){Confirm(o);Paid(o);store.ChangeOrderStatus(o.Id,"Đang chuẩn bị",-1);store.ChangeOrderStatus(o.Id,"Đang giao",-1);store.ChangeOrderStatus(o.Id,"Đã giao",-1);}
var sourcePath=args.Length>0?args[0]:"Project_QLThoiTrang/App_Data/store.json";var source=JsonSerializer.Deserialize<StoreData>(File.ReadAllText(sourcePath))!;
Check("SQL01","27 bảng gốc + 10 bảng mở rộng; không có bảng Products/Customers thay thế",()=>{using var db=factory.CreateDbContext();var tables=db.Model.GetEntityTypes().Select(t=>t.GetTableName()).Distinct().ToList();Assert(tables.Count==37&&!tables.Contains("Products")&&!tables.Contains("Customers"));});
Check("SQL02","Hai script cung cấp tạo đủ 20 khách và 20 nhân viên",()=>Assert(store.NativeRead(db=>db.KhachHang.Count()==20&&db.NhanVien.Count()==20)));
Check("SQL03","Dữ liệu gốc sản phẩm/đơn/trả hàng/phiếu nhập giữ đủ",()=>Assert(store.NativeRead(db=>db.SanPham.Count()==8&&db.DonHang.Count()==4&&db.PhieuTraHang.Count()==1&&db.PhieuNhap.Count()==3&&db.DanhGia.Count()==3)));
Check("AU01","Hash từ bản SQL an toàn xác minh được mật khẩu gốc",()=>Assert(store.Authenticate("ADMIN@SHOP.COM","123456")?.Id==-1));
Check("AU02","Tài khoản kho được ánh xạ đúng quyền Inventory",()=>Assert(store.Authenticate("kho@shop.com","123456")?.Role=="Inventory"));
Check("AU03","Sai mật khẩu ghi nhận thất bại; không xác thực",()=>{int old=store.NativeRead(db=>db.LichSuDangNhap.Count());Assert(store.Authenticate("an@gmail.com","wrong")==null&&store.NativeRead(db=>db.LichSuDangNhap.Count())==old+1);});
Check("DB01","Nhập JSON cùng dữ liệu SQL: giữ cả hai tập dữ liệu",()=>{int old=store.Read(d=>d.Customers.Count);store.ImportJson(sourcePath);Assert(store.Read(d=>d.Products.Count==8+source.Products.Count&&d.Orders.Count==4+source.Orders.Count&&d.Customers.Count==old+source.Customers.Count));});
Check("DB02","Legacy ID ánh xạ đúng; giữ tồn và hash JSON",()=>Assert(store.Read(d=>source.Products.All(p=>d.Products.Single(x=>x.LegacyId==p.Id).Stock==p.Stock)&&source.Customers.All(c=>d.Customers.Single(x=>x.LegacyId==c.Id&&x.Email==c.Email).PasswordHash==c.PasswordHash))));
Check("DB03","Tổng tiền đơn JSON không đổi; không trừ lại kho lịch sử",()=>Assert(store.Read(d=>source.Orders.All(o=>d.Orders.Single(x=>x.Id==o.Id).Total==o.Total))));
Check("DB04","Chặn nhập lại JSON, giữ nguyên số bản ghi",()=>{int count=store.Read(d=>d.Orders.Count);Reject(()=>store.ImportJson(sourcePath));Assert(store.Read(d=>d.Orders.Count)==count);});
