Check("MG04","Tạo biến thể, chặn SKU/tổ hợp trùng",()=>{int size=store.References("sizes").Single(x=>x.Name=="VERIFY-SIZE").Id;int color=store.References("colors").Single(x=>x.Name=="Test color").Id;store.SaveVariant(new(){ProductId=1,SizeId=size,ColorId=color,Sku="VERIFY-XXL",Price=400000},-2);Reject(()=>store.SaveVariant(new(){ProductId=1,SizeId=size,ColorId=color,Sku="VERIFY-XXL"},-2));});
