Order partial=null!;int returnId=0;
Check("RT02","Trả một phần, phân bổ giảm giá",()=>{partial=Place(2,1,"SALE10");Deliver(partial);var l=Get(partial.Id).Lines.First();store.RequestReturn(partial.Id,"Test partial return",1,l.Id,1);var r=store.Read(d=>d.Returns.Single(r=>r.OrderId==partial.Id));returnId=r.Id;Assert(r.Lines.Sum(l=>l.Quantity)==1&&r.Refund==315000);});
Check("RT03","Chặn yêu cầu trả trùng đang chờ",()=>Reject(()=>store.RequestReturn(partial.Id,"Duplicate pending",1)));
Check("RT04","Duyệt trả phần đầu hoàn đúng tiền và kho",()=>{int old=Stock();store.ResolveReturn(returnId,true,"Received restockable goods and refunded","PART-1",-4);Assert(Stock()==old+1&&Get(partial.Id).RefundedAmount==315000&&Get(partial.Id).Status=="Đã giao");});
Check("RT05","Duyệt lặp không hoàn lần nữa",()=>{int old=Stock();Reject(()=>store.ResolveReturn(returnId,true,"Duplicate action","PART-DUP",-4));Assert(Stock()==old);});
Check("RT06","Trả vượt phần còn lại bị chặn",()=>{var l=Get(partial.Id).Lines.First();Reject(()=>store.RequestReturn(partial.Id,"Too many units",1,l.Id,3));});
Check("RT07","Trả nốt hoàn phần còn lại, trạng thái đầy đủ",()=>{store.RequestReturn(partial.Id,"Return remaining goods",1);var r=store.Read(d=>d.Returns.Last(r=>r.OrderId==partial.Id));Assert(r.Refund==315000);store.ResolveReturn(r.Id,true,"Received goods and refunded","PART-2",-1);Assert(Get(partial.Id).RefundedAmount==Get(partial.Id).Total&&Get(partial.Id).Status=="Đã hoàn hàng");});
Check("RT08","Từ chối không đổi kho hoặc tiền",()=>{var o=Place();Deliver(o);store.RequestReturn(o.Id,"Reject fixture",1);var r=store.Read(d=>d.Returns.Single(r=>r.OrderId==o.Id));int old=Stock();store.ResolveReturn(r.Id,false,"Request rejected","",-4);Assert(Stock()==old&&Get(o.Id).RefundedAmount==0);});
