Check("SH02","Tạo đơn xóa giỏ lưu DB cùng transaction",()=>{var cart=store.UserCart(2);var o=store.PlaceOrder(2,Input(),cart);Assert(store.UserCart(2).Count==0&&Get(o.Id).CustomerId==2);});
Check("TX01","Giỏ nhiều dòng sai rollback toàn bộ",()=>{int old=Stock();var cart=Cart();cart.Add(new(){ProductId=999999,VariantId=999999,Quantity=1});Reject(()=>store.PlaceOrder(1,Input(),cart));Assert(Stock()==old);});
Check("TX02","Hai connection mua đơn vị cuối chỉ một thành công",()=>{var v=Variant();var stocks=store.Read(d=>d.Stocks.Where(s=>s.VariantId==v.Id).ToList());foreach(var s in stocks)store.AdjustVariantStock(v.Id,s.WarehouseId,s.WarehouseId==1?1:0,s.Quantity,"Concurrent fixture",-3);var tasks=Enumerable.Range(0,2).Select(_=>Task.Run(()=>{try{store.PlaceOrder(1,Input(),new(){new(){ProductId=v.ProductId,VariantId=v.Id,Size=v.Size,Quantity=1}});return 1;}catch(InvalidOperationException){return 0;}})).ToArray();Task.WaitAll(tasks);Assert(tasks.Sum(t=>t.Result)==1&&store.Read(d=>d.Stocks.Where(s=>s.VariantId==v.Id).Sum(s=>s.Quantity))==0);store.Receive(new(){VariantId=v.Id,WarehouseId=1,SupplierId=1,Quantity=10,UnitCost=1000,Reference="RESTORE-CONCURRENT"},-3);});
Check("TX03","Hai connection thu tiền chỉ một thành công",()=>{var o=Place();Confirm(o);var tasks=Enumerable.Range(0,2).Select(_=>Task.Run(()=>{try{Paid(o);return 1;}catch(InvalidOperationException){return 0;}})).ToArray();Task.WaitAll(tasks);Assert(tasks.Sum(t=>t.Result)==1&&Get(o.Id).PaidAmount==o.Total);});
