Check("AU09","Đổi mật khẩu kiểm tra mật khẩu hiện tại",()=>{var c=store.Read(d=>d.Customers.Single(c=>c.Email=="new@example.test"));Reject(()=>store.ChangePassword(c.Id,new(){CurrentPassword="wrong",NewPassword="Changed@12345",ConfirmPassword="Changed@12345"}));store.ChangePassword(c.Id,new(){CurrentPassword="Verify@12345",NewPassword="Changed@12345",ConfirmPassword="Changed@12345"});Assert(store.Authenticate(c.Email,"Verify@12345")==null&&store.Authenticate(c.Email,"Changed@12345")!=null);});
