Check("PA08","Không tái dùng chứng từ có sẵn trong ThanhToan gốc",()=>{var o=Place();Confirm(o);Reject(()=>store.RecordPayment(o.Id,o.Total,"GD000001",-1));Assert(Get(o.Id).PaidAmount==0);});
Check("RT10","Vượt tồn khi nhận trả rollback cả tiền, phiếu và trạng thái",()=>{var o=Place();Deliver(o);store.RequestReturn(o.Id,"Overflow return fixture",1);var r=store.Read(d=>d.Returns.Last(r=>r.OrderId==o.Id));store.AdjustStock(1,100000,Stock(),"Overflow fixture",-3);int count=store.Read(d=>d.Payments.Count);Reject(()=>store.ResolveReturn(r.Id,true,"Received return fixture","OVERFLOW-REFUND",-1));Assert(Stock()==100000&&Get(o.Id).RefundedAmount==0&&store.Read(d=>d.Returns.Single(x=>x.Id==r.Id).Status=="Pending"&&d.Payments.Count==count));store.AdjustStock(1,100,Stock(),"Restore fixture",-3);});
Check("OR17","Shipping boundary 699000/700000 uses effective variant price",()=>{var variant=Variant();decimal? price=variant.Price;store.Write(d=>{d.Variants.Single(v=>v.Id==variant.Id).Price=699000;return 0;});var a=Place();store.Write(d=>{d.Variants.Single(v=>v.Id==variant.Id).Price=700000;return 0;});var b=Place();Assert(a.Shipping==30000&&b.Shipping==0&&Get(a.Id).Lines.Single().Price==699000);store.Write(d=>{d.Variants.Single(v=>v.Id==variant.Id).Price=price;return 0;});});
Check("TX07","Cân bằng sổ kho sau rollback và kiểm thử ngưỡng",()=>Assert(store.Read(d=>d.Products.All(p=>d.StockMovements.Where(m=>m.ProductId==p.Id).Sum(m=>m.Delta)==p.Stock))));
Check("AU11","Hash giả có marker Identity nhưng header sai bị từ chối và rollback",()=>{var invalid=new byte[61];invalid[0]=1;string hash=Convert.ToBase64String(invalid);Reject(()=>store.Write(d=>{d.Customers.Single(c=>c.Email=="new@example.test").PasswordHash=hash;return 0;}));Assert(store.Authenticate("new@example.test","Changed@12345")!=null);});
Check("AU12","Mật khẩu cũ là chuỗi Base64 dài vẫn được băm; chạy lặp không đổi hash",()=>{var c=store.Read(d=>d.Customers.Single(c=>c.Email=="new@example.test"));string legacy=Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(new string('P',70)));using(var db=factory.CreateDbContext()){var row=db.KhachHang.Single(x=>x.MaKH==c.Id);row.MatKhau=legacy;db.SaveChanges();}Assert(store.Authenticate(c.Email,legacy)==null);Assert(store.HashLegacyPasswords()==1&&store.Authenticate(c.Email,legacy)!=null);string hash=store.CurrentAccount(c.Id)!.PasswordHash;Assert(hash!=legacy&&store.HashLegacyPasswords()==0&&store.CurrentAccount(c.Id)!.PasswordHash==hash);});
Check("AU13","Admin cập nhật hồ sơ khách với điện thoại/địa chỉ trống",()=>{var c=store.Read(d=>d.Customers.Single(c=>c.Email=="new@example.test"));store.UpdateCustomer(c.Id,new(){Name=c.Name,Phone=null!,Address=null!},true,-1);Assert(store.Read(d=>d.Customers.Single(x=>x.Id==c.Id).Phone==""&&d.Customers.Single(x=>x.Id==c.Id).Address==""));});
File.WriteAllText(Environment.GetEnvironmentVariable("QOANH_TEST_REPORT")??"delivery/business-check-results.json",JsonSerializer.Serialize(new{executedUtc=DateTime.UtcNow,database=cs.InitialCatalog,server=cs.DataSource,total=results.Count,failed,results},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"{results.Count-failed}/{results.Count} passed. Test database retained: {cs.InitialCatalog}");return failed==0?0:1;
sealed class Factory(string connection):IDbContextFactory<StoreDbContext>{public StoreDbContext CreateDbContext()=>new(new DbContextOptionsBuilder<StoreDbContext>().UseSqlServer(connection).Options);}
